import { useContext, useEffect, useState } from 'react'
import { Link, Navigate, useNavigate, useSearchParams } from 'react-router-dom'
import banner2 from './images/banner2.png'
import banner1 from './images/banner1.png'
import banner3 from './images/banner3.png'
import { Context } from './usecontext'
import Swal from 'sweetalert2'
import AOS from "aos"
import "aos/dist/aos.css"
import Splide from '@splidejs/splide'
import '@splidejs/splide/css'
import { motion } from 'framer-motion'
import CursorGrid from './CursorGrid'

export const Main = () => {
    const [d, setd] = useState([])
    const [spro, setspro] = useState([])
    const [lpro, setlpro] = useState([])
    const [br, setbr] = useState([])
    const [idd, setidd] = useState()
    const [laptop, setlaptop] = useState([])
    const [mobile, setmobile] = useState([])
    const [led, setled] = useState([])
    const [airpod, setairpod] = useState([])
    const { id } = useContext(Context)
    const [discount, setdiscount] = useState("")
    const [showTop, setShowTop] = useState(false);
    const [scrollProgress, setScrollProgress] = useState(0);

    const navigate = useNavigate()

    useEffect(() => {
        AOS.init({
            duration: 800,
            easing: "ease-in-out",
            once: true,
            offset: 120
        })
    }, [])

    useEffect(() => {
        const timer = setTimeout(() => {
            const el = document.querySelector(".categorySlider");
            const SplideConstructor = Splide || window.Splide?.Splide || window.Splide;
            if (typeof SplideConstructor === "function" && el) {
                try {
                    new SplideConstructor(el, {
                        perPage: 6,
                        gap: 20,
                        autoplay: true,
                        arrows: false,
                        pagination: false,
                        breakpoints: {
                            992: { perPage: 4, arrows: true },
                            768: { perPage: 3, arrows: true },
                            576: { perPage: 2, arrows: true },
                        },
                    }).mount();
                } catch (e) {
                    console.warn("Splide initialization warning:", e);
                }
            }
        }, 300);

        return () => clearTimeout(timer);
    }, [d]);


    useEffect(() => {

        show();
        show2();
        show3();
        show4();
        show5();
        show6()
        show7()
        show8() 

    }, [])

    useEffect(() => {

        const handleScroll = () => {
            setShowTop(window.scrollY > window.innerHeight * 0.2);
            const scrollableHeight = document.documentElement.scrollHeight - window.innerHeight;
            setScrollProgress(scrollableHeight > 0 ? (window.scrollY / scrollableHeight) * 100 : 0);
        };

        handleScroll();
        window.addEventListener("scroll", handleScroll);
        window.addEventListener("resize", handleScroll);

        return () => {
            window.removeEventListener("scroll", handleScroll);
            window.removeEventListener("resize", handleScroll);
        };

    }, []);





   const show = async () => {
    try {
        const result = await fetch("https://elcto-1.onrender.com/api/getcategory");

        const res = await result.json();

        if (res.statuscode === 1) {
            setd(res.data);
            setidd(res.data[0]?.Category);
        } else {
            alert("Error from API");
        }
    } catch (err) {
        console.error("Fetch error:", err);
    }
};
    const show2 = async () => {
        const result = await fetch("https://elcto-1.onrender.com/api/saleproduct", {
            method: "get"
        })
        if (result.ok) {
            const res = await result.json()
            if (res.statuscode === 1) {

                setspro(res.data)
            }
            else {
                alert("bbfb")
            }
        }
    }
    const show3 = async () => {
        const result = await fetch("https://elcto-1.onrender.com/api/latestproduct", {
            method: "get"
        })
        if (result.ok) {
            const res = await result.json()
            if (res.statuscode === 1) {
                setlpro(res.data)
            }
            else {
                alert("bbfb")
            }
        }
    }
    const show4 = async () => {
        const result = await fetch(" https://elcto-1.onrender.com/api/showbrand", {
            method: "get"
        })
        if (result) {
            const res = await result.json()
            if (res.statuscode === 1) {
                setbr(res.data)
            }
            else {
                alert("rere")
            }
        }
    }
    const show5 = async () => {
        const result = await fetch(`https://elcto-1.onrender.com/api/laptop`, {
            method: "get"
        })
        if (result.ok) {
            const res = await result.json()
            if (res.statuscode === 1) {
                setlaptop(res.data)

            }
            else {
                alert("not found")
            }
        }
    }
    const show6 = async () => {
        const result = await fetch("https://elcto-1.onrender.com/api/mobiles", {
            method: "get"
        })
        if (result) {
            const res = await result.json()
            if (res.statuscode === 1) {
                setmobile(res.data)
            }
            else {
                alert("sdfg")
            }
        }
    }
    const show7 = async () => {
        const result = await fetch("https://elcto-1.onrender.com/api/leds", {
            method: "get"
        })
        if (result) {
            const res = await result.json()
            if (res.statuscode === 1) {
                setled(res.data)
            }
            else {
                alert("dfg")
            }
        }
    }
    const show8 = async () => {
        const result = await fetch("https://elcto-1.onrender.com/api/airpods", {
            method: "get"
        })
        if (result) {
            const res = await result.json()
            if (res.statuscode === 1) {
                setairpod(res.data)
            }
            else {
                alert("d")
            }
        }
    }

    const wish = async (id, name, price, img, prr,saleprice) => {
          if (!id) {
        Swal.fire({
            icon: "warning",
            title: "Please Login First",
            text: "Login to add items to cart"
        })
        navigate("/login")
        return
    }

        const data = { id, name, price, img, prr, saleprice }
        const result = await fetch(`https://elcto-1.onrender.com/api/wishpost/${prr}`, {
            method: "post",
            body: JSON.stringify(data),
            headers: { "Content-type": "application/json;charset=UTF-8" }
        })
        if (result.ok) {
            const res = await result.json();

            if (res.statuscode === 2) {
                Swal.fire({
                    icon: "info",
                    title: "❤️ Already in Wishlist",
                    text: (res.message)
                })
            }

            else if (res.statuscode === 1) {
                navigate(`/wish?id=${id}`);
                Swal.fire({
                    icon: "success",
                    title: "❤️ Added in Wishlist",
                })
            }

            else {
                alert("Something went wrong");
            }

        }
    }
    const cart = async (id, name, price, img, value = 1, prr) => {
          if (!id) {
        Swal.fire({
            icon: "warning",
            title: "Please Login First",
            text: "Login to add items to cart"
        })
        navigate("/login")
        return
    }

        const data = { id, name, price, img, value }
        const result = await fetch(`https://elcto-1.onrender.com/api/cartdata/${prr}`, {
            method: "post",
            body: JSON.stringify(data),
            headers: { "Content-type": "application/json;charset=UTF-8" }
        })
        if (result.ok) {
            const res = await result.json()
            if (res.statuscode === 2) {
                Swal.fire({
                    icon: "info",
                    title: "🛒 Already in Cart",
                    text: (res.message)
                });

            }
            else if (res.statuscode === 1) {
                navigate(`/cart?id=${id}`)
                Swal.fire({
                    icon: "success",
                    text: "🛒 Added to Cart"
                })
            }
            else {
                alert("dfg")
            }
        }
    }
    const gotop = () => {
        window.scrollTo({
            top: 0,
            behavior: 'smooth'
        })
    }
    const calculateDiscount = (original, sale) => {
        return Math.round(((original - sale) / original) * 100);
    }



    return (
        <>
    <div className='container-fluid px-0 px-md-3 py-2 py-md-3'>
        <style>{`
            @keyframes heroFadeInUp {
                from {
                    opacity: 0;
                    transform: translateY(24px);
                }
                to {
                    opacity: 1;
                    transform: translateY(0);
                }
            }
            @keyframes heroBadgePop {
                from {
                    opacity: 0;
                    transform: scale(0.85);
                }
                to {
                    opacity: 1;
                    transform: scale(1);
                }
            }
            @keyframes progressTimer {
                from { width: 0%; }
                to { width: 100%; }
            }

            .modern-hero-carousel {
                border-radius: 26px;
                overflow: hidden;
                box-shadow: 0 25px 60px -15px rgba(15, 23, 42, 0.28);
                position: relative;
                background: #090d16;
            }
            @media (max-width: 768px) {
                .modern-hero-carousel {
                    border-radius: 18px;
                }
            }
            .modern-hero-carousel .carousel-item {
                position: relative;
                overflow: hidden;
            }
            .modern-hero-carousel .carousel-img-wrapper {
                position: relative;
                width: 100%;
                height: clamp(340px, 50vw, 620px);
                overflow: hidden;
            }
            .modern-hero-carousel .carousel-img-wrapper img {
                width: 100%;
                height: 100%;
                object-fit: cover;
                object-position: center;
                transition: transform 9s cubic-bezier(0.25, 1, 0.5, 1);
            }
            .modern-hero-carousel .carousel-item.active .carousel-img-wrapper img {
                transform: scale(1.08);
            }

            .modern-hero-carousel .carousel-overlay {
                position: absolute;
                inset: 0;
                background: 
                    radial-gradient(circle at 75% 40%, rgba(15, 98, 254, 0.22) 0%, transparent 55%),
                    linear-gradient(90deg, rgba(8, 12, 24, 0.88) 0%, rgba(8, 12, 24, 0.55) 50%, rgba(8, 12, 24, 0.15) 100%);
                z-index: 1;
            }
            @media (max-width: 768px) {
                .modern-hero-carousel .carousel-overlay {
                    background: linear-gradient(180deg, rgba(8, 12, 24, 0.25) 0%, rgba(8, 12, 24, 0.92) 100%);
                }
            }

            .modern-hero-carousel .carousel-caption-content {
                position: absolute;
                inset: 0;
                z-index: 2;
                display: flex;
                flex-direction: column;
                justify-content: center;
                align-items: flex-start;
                padding: 2.5rem clamp(1.5rem, 6vw, 5.5rem);
                color: #ffffff;
                text-align: left;
            }
            @media (max-width: 768px) {
                .modern-hero-carousel .carousel-caption-content {
                    justify-content: flex-end;
                    padding-bottom: 4rem;
                }
            }

            .carousel-item.active .hero-badge-animated {
                animation: heroBadgePop 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
            }
            .carousel-item.active .hero-title-animated {
                animation: heroFadeInUp 0.7s cubic-bezier(0.16, 1, 0.3, 1) 0.15s forwards;
                opacity: 0;
            }
            .carousel-item.active .hero-desc-animated {
                animation: heroFadeInUp 0.7s cubic-bezier(0.16, 1, 0.3, 1) 0.3s forwards;
                opacity: 0;
            }
            .carousel-item.active .hero-actions-animated {
                animation: heroFadeInUp 0.7s cubic-bezier(0.16, 1, 0.3, 1) 0.45s forwards;
                opacity: 0;
            }

            .modern-carousel-btn {
                position: absolute;
                top: 50%;
                transform: translateY(-50%);
                z-index: 5;
                width: 52px;
                height: 52px;
                border-radius: 50%;
                background: rgba(255, 255, 255, 0.12);
                backdrop-filter: blur(16px);
                -webkit-backdrop-filter: blur(16px);
                border: 1px solid rgba(255, 255, 255, 0.25);
                color: #ffffff;
                display: flex;
                align-items: center;
                justify-content: center;
                font-size: 1.25rem;
                cursor: pointer;
                transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
                opacity: 0.85;
            }
            .modern-carousel-btn:hover {
                background: rgba(255, 255, 255, 0.95);
                color: #0f172a;
                transform: translateY(-50%) scale(1.12);
                box-shadow: 0 12px 30px rgba(0, 0, 0, 0.3);
                opacity: 1;
            }
            .modern-carousel-btn.prev-btn { left: 22px; }
            .modern-carousel-btn.next-btn { right: 22px; }
            @media (max-width: 576px) {
                .modern-carousel-btn {
                    width: 38px;
                    height: 38px;
                    font-size: 1rem;
                }
                .modern-carousel-btn.prev-btn { left: 10px; }
                .modern-carousel-btn.next-btn { right: 10px; }
            }

            .custom-carousel-indicators {
                position: absolute;
                bottom: 20px;
                left: 50%;
                transform: translateX(-50%);
                z-index: 5;
                display: flex;
                gap: 8px;
                margin: 0;
                padding: 6px 14px;
                background: rgba(10, 16, 30, 0.45);
                backdrop-filter: blur(12px);
                -webkit-backdrop-filter: blur(12px);
                border-radius: 30px;
                border: 1px solid rgba(255, 255, 255, 0.18);
            }
            .custom-carousel-indicators button {
                width: 10px;
                height: 10px;
                border-radius: 50%;
                border: none;
                background-color: rgba(255, 255, 255, 0.4);
                transition: all 0.4s ease;
                padding: 0;
                cursor: pointer;
            }
            .custom-carousel-indicators button.active {
                width: 32px;
                border-radius: 12px;
                background-color: #ffffff;
                box-shadow: 0 0 14px rgba(255, 255, 255, 0.7);
            }

            .hero-badge {
                display: inline-flex;
                align-items: center;
                gap: 8px;
                padding: 7px 16px;
                border-radius: 30px;
                font-size: 0.78rem;
                font-weight: 700;
                letter-spacing: 0.09em;
                text-transform: uppercase;
                margin-bottom: 16px;
                backdrop-filter: blur(10px);
                box-shadow: 0 4px 18px rgba(0, 0, 0, 0.2);
            }
            .hero-title {
                font-size: clamp(2rem, 4.5vw, 3.6rem);
                font-weight: 800;
                line-height: 1.12;
                letter-spacing: -0.025em;
                text-shadow: 0 4px 16px rgba(0, 0, 0, 0.4);
                margin-bottom: 14px;
                max-width: 680px;
            }
            .hero-desc {
                font-size: clamp(0.92rem, 1.5vw, 1.15rem);
                color: rgba(255, 255, 255, 0.88);
                max-width: 540px;
                margin-bottom: 26px;
                line-height: 1.55;
            }

            .hero-primary-btn {
                padding: 13px 30px;
                border-radius: 30px;
                font-weight: 700;
                font-size: 0.95rem;
                transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
                display: inline-flex;
                align-items: center;
                gap: 8px;
                text-decoration: none;
                box-shadow: 0 10px 25px rgba(0, 0, 0, 0.25);
            }
            .hero-primary-btn:hover {
                transform: translateY(-3px) scale(1.02);
                box-shadow: 0 16px 35px rgba(0, 0, 0, 0.35);
            }
            .hero-secondary-btn {
                padding: 13px 26px;
                border-radius: 30px;
                font-weight: 600;
                font-size: 0.95rem;
                transition: all 0.3s ease;
                display: inline-flex;
                align-items: center;
                gap: 8px;
                text-decoration: none;
                color: #ffffff;
                background: rgba(255, 255, 255, 0.12);
                backdrop-filter: blur(12px);
                border: 1px solid rgba(255, 255, 255, 0.3);
            }
            .hero-secondary-btn:hover {
                background: rgba(255, 255, 255, 0.25);
                color: #ffffff;
                transform: translateY(-2px);
            }

            .hero-trust-bar {
                display: grid;
                grid-template-columns: repeat(4, 1fr);
                gap: 12px;
                margin-top: 16px;
                padding: 16px 24px;
                background: #ffffff;
                border-radius: 20px;
                box-shadow: 0 10px 30px rgba(15, 23, 42, 0.06);
                border: 1px solid rgba(229, 231, 235, 0.8);
            }
            @media (max-width: 768px) {
                .hero-trust-bar {
                    grid-template-columns: repeat(2, 1fr);
                    gap: 14px;
                    padding: 14px;
                }
            }
            .trust-item {
                display: flex;
                align-items: center;
                gap: 12px;
            }
            .trust-icon {
                width: 42px;
                height: 42px;
                border-radius: 12px;
                background: #eef4ff;
                color: #0f62fe;
                display: flex;
                align-items: center;
                justify-content: center;
                font-size: 1.2rem;
                flex-shrink: 0;
            }
            .trust-text strong {
                display: block;
                font-size: 0.85rem;
                color: #1e293b;
                font-weight: 700;
                line-height: 1.2;
            }
            .trust-text span {
                font-size: 0.75rem;
                color: #64748b;
            }
        `}</style>

        <div id="carouselExample" className='carousel slide carousel-fade modern-hero-carousel' data-bs-ride="carousel" data-bs-interval="4500">
            <CursorGrid
                cellSize={65}
                color="#00d2ff"
                radius={160}
                falloff="smooth"
                holdTime={450}
                fadeDuration={750}
                lineWidth={1.2}
                maxOpacity={0.8}
                fillOpacity={0.06}
                gridOpacity={0.12}
                cellRadius={4}
                clickPulse={true}
                pulseSpeed={600}
            />

            <div className="custom-carousel-indicators">
                <button type="button" data-bs-target="#carouselExample" data-bs-slide-to="0" className="active" aria-current="true" aria-label="Slide 1"></button>
                <button type="button" data-bs-target="#carouselExample" data-bs-slide-to="1" aria-label="Slide 2"></button>
                <button type="button" data-bs-target="#carouselExample" data-bs-slide-to="2" aria-label="Slide 3"></button>
            </div>

            <div className='carousel-inner'>
                <div className='carousel-item active'>
                    <div className="carousel-img-wrapper">
                        <img src={banner1} alt="Next-Gen Electronics Banner" />
                        <div className="carousel-overlay"></div>
                    </div>
                    <div className="carousel-caption-content">
                        <div className="hero-badge hero-badge-animated text-white" style={{ background: 'linear-gradient(135deg, #0d6efd, #00d2ff)', border: '1px solid rgba(255, 255, 255, 0.35)' }}>
                            <i className="bi bi-lightning-charge-fill"></i> Flagship Store 2026
                        </div>
                        <h1 className="hero-title hero-title-animated text-white">Next-Gen Tech & Smart Devices</h1>
                        <p className="hero-desc hero-desc-animated d-none d-sm-block">Upgrade your digital lifestyle with high-speed smartphones, flagship accessories, and pro audio electronics.</p>
                        <div className="d-flex gap-3 flex-wrap hero-actions-animated">
                            <motion.div whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}>
                                <Link to="/related" className="hero-primary-btn bg-white text-dark">
                                    Shop Collection <i className="bi bi-arrow-right-short fs-5"></i>
                                </Link>
                            </motion.div>
                            <motion.div whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}>
                                <a href="#sale" className="hero-secondary-btn">
                                    Explore Deals <i className="bi bi-fire text-warning"></i>
                                </a>
                            </motion.div>
                        </div>
                    </div>
                </div>

                <div className='carousel-item'>
                    <div className="carousel-img-wrapper">
                        <img src={banner2} alt="High-Performance Laptops Banner" />
                        <div className="carousel-overlay"></div>
                    </div>
                    <div className="carousel-caption-content">
                        <div className="hero-badge hero-badge-animated text-white" style={{ background: 'linear-gradient(135deg, #dc3545, #ff6b6b)', border: '1px solid rgba(255, 255, 255, 0.35)' }}>
                            <i className="bi bi-cpu-fill"></i> Pro Workstations & Gaming
                        </div>
                        <h1 className="hero-title hero-title-animated text-white">Extreme Performance Laptops</h1>
                        <p className="hero-desc hero-desc-animated d-none d-sm-block">Unleash unmatched speed, stunning display graphics, and supreme battery efficiency built for creator workflows.</p>
                        <div className="d-flex gap-3 flex-wrap hero-actions-animated">
                            <motion.div whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}>
                                <Link to="/related" className="hero-primary-btn text-white" style={{ background: 'linear-gradient(135deg, #dc3545, #b02a37)' }}>
                                    View Laptops <i className="bi bi-laptop fs-6 ms-1"></i>
                                </Link>
                            </motion.div>
                            <motion.div whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}>
                                <Link to="/related" className="hero-secondary-btn">
                                    Compare Specs <i className="bi bi-sliders"></i>
                                </Link>
                            </motion.div>
                        </div>
                    </div>
                </div>

                <div className='carousel-item'>
                    <div className="carousel-img-wrapper">
                        <img src={banner3} alt="Immersive Audio Banner" />
                        <div className="carousel-overlay"></div>
                    </div>
                    <div className="carousel-caption-content">
                        <div className="hero-badge hero-badge-animated text-dark" style={{ background: 'linear-gradient(135deg, #ffc107, #ff9800)', border: '1px solid rgba(255, 255, 255, 0.35)' }}>
                            <i className="bi bi-headphones"></i> Audiophile Studio Sound
                        </div>
                        <h1 className="hero-title hero-title-animated text-white">Immersive Sound & Wireless Pods</h1>
                        <p className="hero-desc hero-desc-animated d-none d-sm-block">Deep bass, active noise-cancellation, and crystal-clear acoustic clarity designed for pure musical immersion.</p>
